41|if (! function_exists('jalali_date_time')) {
42|    /**
43|     * نمایش شمسی تاریخ و ساعت — برای لاگ‌ها و زمان ثبت رخداد.
44|     */
45|    function jalali_date_time(string|int|DateTimeInterface|null $date, string $format = 'Y/m/d H:i'): ?string
46|    {
47|        return jalali_date($date, $format);
48|    }
49|}
50|
51|if (! function_exists('miladi_date')) {
52|    /**
53|     * تبدیل تاریخ شمسی ورودی کاربر به میلادی قابل ذخیره.
54|     * ورودی کاربر هم ارقام فارسی و هم ارقام لاتین و هم جداکننده‌های متنوع را می‌پذیرد.
55|     *
56|     * @throws InvalidArgumentException اگر تاریخ شمسی معتبر نباشد
57|     */
58|    function miladi_date(?string $date, string $format = 'Y-m-d'): ?string
59|    {
60|        if (blank($date)) {
61|            return null;
62|        }
63|
64|        $normalized = normalize_jalali_input($date);
65|
66|        if (! preg_match('#^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})$#', $normalized, $m)) {
67|            throw new InvalidArgumentException("قالب تاریخ شمسی نامعتبر است: {$date} (باید به شکل ۱۴۰۳/۰۵/۱۲ باشد)");
68|        }
69|
70|        [, $year, $month, $day] = $m;
71|
72|        $year = (int) $year;
73|        $month = (int) $month;
74|        $day = (int) $day;
75|
76|        $maxDay = jalali_month_days($year, $month);
77|
78|        if ($day > $maxDay) {
79|            throw new InvalidArgumentException(
80|                "روز {$day} در ماه {$month} سال {$year} وجود ندارد (بیشترین روز: {$maxDay})"
81|            );
82|        }
83|
84|        return (new Jalalian($year, $month, $day))->toCarbon()->format($format);
85|    }
86|}
